mapper.select:
/** [sql-consignedMaterialsReg.xml] ConsignedMaterialsRegMapper.getProdStockList **/ select st01_lot, st02_dat, st01_code, cm08_name, cm08_gbn, cm08_dgbn, st01_qty, st01_unt, st01_stok, st01_district, st01_lot_seq, st02_qrcode, st02_moq, sum(st01.st01_qty) as st01_qty from tb_st_01 st01 left join tb_cm_08 cm08 on cm08.cm08_company = st01.st01_company and cm08.cm08_factory = st01.st01_factory and cm08.cm08_code = st01.st01_code left join tb_st_02 st02 on st02.st02_company = st01.st01_company and st02.st02_factory = st01.st01_factory and st02.st02_lot = st01.st01_lot and st02.st02_lot_seq = st01.st01_lot_seq where 1 = 1 and st01_company = #{company} and st01_factory = #{factory} and st01_code = #{st01Code} and st01_qty > 0
AND st01_lot = #{lot}
AND st01_lot_seq = #{lotSeq}
group by st01_lot,st02_dat,st01_code,cm08_name,cm08_gbn,cm08_dgbn,st01_qty,st01_unt,st01_stok,st01_district,st01_lot_seq,st02_qrcode,st02_moq order by ST01_CODE, ST01_LOT, ST01_LOT_SEQ
